-- The sheet's fiscal year start month (not dated), 1 to 12: a fiscal year runs from its first day.
ALTER TABLE sheet ADD COLUMN fiscal_start_month INTEGER NOT NULL DEFAULT 1;
-- A claim's number: given when the claim is opened, the next on its sheet (1, 2, ...), never
-- reused. A DRAFT claim has none; voiding a claim clears it. The sheet keeps the last number given.
ALTER TABLE sheet ADD COLUMN last_claim_number BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number BIGINT;
CREATE UNIQUE INDEX claim_sheet_number ON claim (sheet_id, claim_number);
-- The sheet's period numbering from: while set and the sheet's today is on or after it, a claim
-- opened is numbered within its period (<period name>-<n>), or X-<n> when in no period. Empty: off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number is now text: the sheet-wide number (1, 2, ...) or a number within a period.
-- A correction names the number of the claim it corrects in the same form.
DROP INDEX claim_sheet_number;
ALTER TABLE claim ALTER COLUMN claim_number VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(220);
-- A claim numbered within a period: the period's name (empty: in no period) and its place in it.
ALTER TABLE claim ADD COLUMN number_period VARCHAR(200);
ALTER TABLE claim ADD COLUMN number_seq INT;
-- The sheet a sheet names as its parent (not dated): a grade with no rate in force on a date on the
-- sheet takes its parent's, then its parent's parent's, up to three levels up. Kept apart from the
-- sheet's own rows (no sheet_id column, no reference) so its history leaves it as it is now: the
-- link between sheets is not part of what either sheet held on a date.
CREATE TABLE sheet_parent (
    child_sheet  VARCHAR(100) PRIMARY KEY,
    parent_sheet VARCHAR(100) NOT NULL
);
