test("numbering per fiscal year scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  await ui.setSetting(pg_uma, "pot", "33.33");
  await ui.setSetting(pg_uma, "fiscal-start-month", "7");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00", "from": "2026-03-01"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "tags": "c"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "70.00", "from": "2026-03-01", "to": "2026-04-30"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "20.00", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.retire(pg_uma, p_cam, "2026-03-05")).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.addAlias(pg_uma, p_ada, "Bee")).toBe(true);
  expect(await ui.statementAsOf(pg_uma, p_ada, "2026-04-02")).toBe(false);
  expect(await ui.addClaim(pg_uma, p_cam, {"amount": "12.50", "date": "2026-03-20", "note": "n", "ref": "R-1"})).toBeNull();
  expect(await ui.addClaim(pg_uma, p_cam, {"amount": "99.95", "note": "n"})).toBeNull();
  const c_ada_0 = ui.must(await ui.addClaimTwice(pg_uma, p_ada, {"amount": "1.00", "date": "2026-04-02"}));
  expect(await ui.claimCount(pg_uma, p_ada)).toBe(1);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("DRAFT");
